def normalize(value):
    value=re.sub(r'\s+',' ',value.strip())
    return re.sub(r'\s*([=><.])\s*',r'\1',value)
def validate_challenge(c,answer):
    return normalize(answer) in {normalize(a) for a in c['answers']}
